def backfill(apps, schema_editor):
    """Employee links from the approvals that checked an employee ID, and the requester each
    stored message was typed as. A message whose requester cannot be told for sure (typed before
    approval, with no anonymous requester) stays empty, so the requester page never shows it."""
    AuditEvent = apps.get_model("operations", "AuditEvent")
    Employee = apps.get_model("operations", "Employee")
    Requester = apps.get_model("operations", "Requester")
    Message = apps.get_model("operations", "ConversationMessage")

    approvals = AuditEvent.objects.filter(
        action__in=["registration.approved", "registration.auto_approved"]
    )
    for event in approvals.iterator():
        employee_id, requester_id = event.data.get("employee"), event.data.get("requester_id")
        employee = Employee.objects.filter(employee_id=employee_id).first() if employee_id else None
        if employee is not None and requester_id:
            Requester.objects.filter(pk=requester_id).update(
                employee=employee, employee_link="verified"
            )

    anonymous = dict(
        Requester.objects.filter(anonymous_identity__isnull=False).values_list(
            "anonymous_identity_id", "pk"
        )
    )
    changed = []
    rows = Message.objects.filter(requester__isnull=True).select_related(
        "draft", "case", "identity__requester"
    )
    for message in rows.iterator(chunk_size=500):
        if message.draft_id:
            message.requester_id = message.draft.requester_id
        elif message.case_id:
            message.requester_id = message.case.requester_id
        else:
            owner = message.identity.requester
            approved = owner is not None and not owner.is_anonymous
            if approved and owner.approved_at <= message.created_at:
                message.requester_id = owner.pk
            else:
                message.requester_id = anonymous.get(message.identity_id)
        if message.requester_id:
            changed.append(message)
    Message.objects.bulk_update(changed, ["requester"], batch_size=500)


